  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 100), 2); // old price: 100

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(200), // new price: 200
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(400); // 200 * 2
    expect(result.lines[0]!.product.unitPriceCents).toBe(200);
  });

  it("checks inventory and throws InventoryError on denial", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 100), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      } satisfies InventoryDecision),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(2);
      expect(err.message).toBe("low stock");
    }
  });

  it("throws InventoryError on partial-stock denial (available < requested)", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 100), 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      } satisfies InventoryDecision),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
  });

  it("passes when inventory is available", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 100), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      } satisfies InventoryDecision),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(200);
  });

  it("uses asyncTaxProvider for async tax computation", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ discountPolicy, region: "US-CA" });
    cart.add(mkProduct("a", 10000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1), // 10%
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(1000); // 10% of 10000
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("combines price refresh + inventory check + async tax + discount + shipping", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({
      discountPolicy,
      shippingCalculator,
      region: "US",
    });
    cart.add(mkProduct("a", 100), 2); // will be repriced to 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1000),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    // subtotal: 1000*2 = 2000
    // discount: 500
    // discounted subtotal: 1500
    // tax: 8% of 1500 = 120
    // shipping: 599
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(500);
    expect(result.totals.taxCents).toBe(120);
    expect(result.totals.shippingCents).toBe(599);
    expect(result.totals.totalCents).toBe(1500 + 120 + 599);
  });

  it("generates default denial message when reason is not provided", async () => {
    const cart = new Cart();
    cart.add(mkProduct("widget", 100), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
      } satisfies InventoryDecision),
    };

    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.message).toContain("widget");
      expect(err.available).toBe(undefined);
    }
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 100), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service error")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service error",
    );
  });

  it("does not modify internal cart state after checkout", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 500), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    await cart.checkout({ priceFetcher });

    // Internal price should still be 500
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(500);
    expect(cart.totals().subtotalCents).toBe(1000);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 999_99, -50])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 as 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent", () => {
      // 33% of 100 = 33.0; 33% of 101 = 33.33 → 33
      const policy = new PercentageDiscountPolicy(33);
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("100% discount equals subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])("rejects negative amountCents %i", (amt) => {
      expect(() => new FixedAmountDiscountPolicy(amt)).toThrow(RangeError);
    });

    it("rejects non-integer amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps discount at subtotal when subtotal is smaller", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(200)).toBe(200);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns subtotal when fixed amount equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 10000 = 1000
      const p2 = new FixedAmountDiscountPolicy(500); // fixed 500
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child discount to 0 before summing", () => {
      // NoDiscountPolicy returns 0, so sum is just the percentage
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("defaults to sum mode when mode not specified", () => {
      const p1 = new FixedAmountDiscountPolicy(200);
      const p2 = new FixedAmountDiscountPolicy(300);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      expect(composite.computeDiscountCents(1000)).toBe(500);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      // 10% of 10000 = 1000, remaining 9000; then 10% of 9000 = 900
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("ordering matters: larger discount first yields different result", () => {
      // 50% of 1000=500 remaining=500, fixed 300 of 500=300 → total 800
      const big = new PercentageDiscountPolicy(50);
      const fixed = new FixedAmountDiscountPolicy(300);
      const a = new CompositeDiscountPolicy([big, fixed], "chain");
      // fixed 300 of 1000=300 remaining=700, 50% of 700=350 → total 650
      const b = new CompositeDiscountPolicy([fixed, big], "chain");
      expect(a.computeDiscountCents(1000)).toBe(800);
      expect(b.computeDiscountCents(1000)).toBe(650);
    });

    it("stops reducing when remaining reaches 0", () => {
      const p1 = new FixedAmountDiscountPolicy(1000);
      const p2 = new FixedAmountDiscountPolicy(500);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // first eats entire 1000, remaining=0, second gets 0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

