describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 10.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 for zero-weight items", () => {
      expect(calc.computeShippingCents([mkLine("a", 1, 100)], 1000)).toBe(0);
    });

    it("selects first bracket for weight within it", () => {
      // 200g item qty 1 = 200g, fits in <=500g bracket
      const lines = [mkLine("a", 1, 100, 200)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      // exactly 500g → first bracket
      const lines = [mkLine("a", 1, 100, 500)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("moves to next bracket when weight exceeds boundary", () => {
      // 501g → second bracket (<=2000g)
      const lines = [mkLine("a", 1, 100, 501)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("selects highest bracket at its boundary", () => {
      // exactly 5000g → third bracket
      const lines = [mkLine("a", 1, 100, 5000)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // 6000g > 5000g → overflow = 2000
      const lines = [mkLine("a", 1, 100, 6000)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflowCostCents", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      const lines = [mkLine("a", 1, 100, 3000)];
      expect(noOverflow.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      const lines = [mkLine("a", 1, 100, 400)];
      expect(unordered.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("sums weights across multiple lines", () => {
      // 2 items × 300g + 1 item × 500g = 1100g → <=2000g bracket
      const lines = [
        mkLine("a", 2, 100, 300),
        mkLine("b", 1, 100, 500),
      ];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });
  });
});

