const mkProduct = (
  id: string,
  priceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: id,
  unitPriceCents: priceCents,
  weightGrams,
});

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty with 0 items", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("add() inserts a new line", () => {
    cart.add(mkProduct("a", 500), 2);
    expect(cart.itemCount).toBe(2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);
  });

  it("add() merges quantity for the same product", () => {
    cart.add(mkProduct("a", 500), 2);
    cart.add(mkProduct("a", 500), 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0]!.quantity).toBe(5);
  });

  it("add() rejects non-positive quantity", () => {
    expect(() => cart.add(mkProduct("a", 100), 0)).toThrow(RangeError);
    expect(() => cart.add(mkProduct("a", 100), -1)).toThrow(RangeError);
    expect(() => cart.add(mkProduct("a", 100), 1.5)).toThrow(RangeError);
  });

  it("add() rejects negative unitPriceCents", () => {
    expect(() => cart.add(mkProduct("a", -1), 1)).toThrow(RangeError);
  });

  it("remove() deletes existing product and returns true", () => {
    cart.add(mkProduct("a", 500), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove() returns false for unknown id", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity() changes the quantity", () => {
    cart.add(mkProduct("a", 500), 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity(0) removes the product", () => {
    cart.add(mkProduct("a", 500), 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("updateQuantity() throws for unknown product", () => {
    expect(() => cart.updateQuantity("ghost", 5)).toThrow(
      "Product ghost is not in the cart",
    );
  });

  it("updateQuantity() rejects negative quantity", () => {
    cart.add(mkProduct("a", 500), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity() rejects non-integer quantity", () => {
    cart.add(mkProduct("a", 500), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear() removes all items", () => {
    cart.add(mkProduct("a", 100), 1);
    cart.add(mkProduct("b", 200), 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot() returns a deep copy that doesn't affect cart", () => {
    cart.add(mkProduct("a", 500), 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    // Cart's internal state is unchanged
    expect(cart.snapshot()[0]!.quantity).toBe(2);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(500);
  });
});

describe("Cart — pricing pipeline (totals)", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2); // 2000
    cart.add(mkProduct("b", 500), 3); // 1500
    const t = cart.totals();
    expect(t.subtotalCents).toBe(3500);
  });

  it("applies discount then tax on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1000),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(250),
    };
    const cart = new Cart({ discountPolicy, taxCalculator });
    cart.add(mkProduct("a", 5000), 1); // subtotal = 5000

    const t = cart.totals();
    expect(t.subtotalCents).toBe(5000);
    expect(t.discountCents).toBe(1000);
    // Tax is computed on discounted subtotal (5000 - 1000 = 4000)
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(4000, "US");
    expect(t.taxCents).toBe(250);
    expect(t.totalCents).toBe(4000 + 250); // discounted + tax + 0 shipping
  });

  it("clamps discount to [0, subtotal]", () => {
    // Discount returning more than subtotal
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(mkProduct("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
    expect(t.totalCents).toBe(0); // nothing left
  });

  it("clamps negative discount to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(mkProduct("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
  });

  it("passes lines and discounted subtotal to shipping calculator", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(mkProduct("a", 1000), 1); // subtotal=1000, discount=200, discounted=800

    const t = cart.totals();
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800,
    );
    expect(t.shippingCents).toBe(599);
    expect(t.totalCents).toBe(800 + 0 + 599); // discounted + tax + shipping
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses default config when none provided", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const t = cart.totals();
    // NoDiscount → 0, NoTax → 0, FreeShipping → 0
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });

  it("empty cart totals are all zero", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("uses the region from config for tax", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator, region: "FR" });
    cart.add(mkProduct("a", 1000), 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });
});

