describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 10000 = 1000
      const p2 = new FixedAmountDiscountPolicy(500); // fixed 500
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child discount to 0 before summing", () => {
      // NoDiscountPolicy returns 0, so sum is just the percentage
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("defaults to sum mode when mode not specified", () => {
      const p1 = new FixedAmountDiscountPolicy(200);
      const p2 = new FixedAmountDiscountPolicy(300);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      expect(composite.computeDiscountCents(1000)).toBe(500);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      // 10% of 10000 = 1000, remaining 9000; then 10% of 9000 = 900
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("ordering matters: larger discount first yields different result", () => {
      // 50% of 1000=500 remaining=500, fixed 300 of 500=300 → total 800
      const big = new PercentageDiscountPolicy(50);
      const fixed = new FixedAmountDiscountPolicy(300);
      const a = new CompositeDiscountPolicy([big, fixed], "chain");
      // fixed 300 of 1000=300 remaining=700, 50% of 700=350 → total 650
      const b = new CompositeDiscountPolicy([fixed, big], "chain");
      expect(a.computeDiscountCents(1000)).toBe(800);
      expect(b.computeDiscountCents(1000)).toBe(650);
    });

    it("stops reducing when remaining reaches 0", () => {
      const p1 = new FixedAmountDiscountPolicy(1000);
      const p2 = new FixedAmountDiscountPolicy(500);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // first eats entire 1000, remaining=0, second gets 0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});
"}

