toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine, Product } from "../src/product.ts";

const mkProduct = (id: string, priceCents = 100): Product => ({
  id,
  name: id,
  unitPriceCents: priceCents,
});

describe("InventoryError", () => {
  it("exposes productId, requested, and available", () => {
    const err = new InventoryError("out of stock", "p1", 5, 2);
    expect(err.productId).toBe("p1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
    expect(err.message).toBe("out of stock");
    expect(err.name).toBe("InventoryError");
    expect(err).toBeInstanceOf(Error);
  });

  it("supports undefined available", () => {
    const err = new InventoryError("gone", "p2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  it("updates unitPriceCents from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const lines: CartLine[] = [
      { product: mkProduct("p1", 100), quantity: 2 },
    ];
    const result = await refreshPrices(lines, fetcher);
    expect(result).toHaveLength(1);
    expect(result[0]!.product.unitPriceCents).toBe(999);
    expect(result[0]!.quantity).toBe(2);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
  });

  it("preserves other product fields", async () => {
    const product: Product = {
      id: "p1",
      name: "Widget",
      unitPriceCents: 100,
      weightGrams: 500,
      currency: "EUR",
    };
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(200),
    };
    const result = await refreshPrices([{ product, quantity: 1 }], fetcher);
    expect(result[0]!.product.name).toBe("Widget");
    expect(result[0]!.product.weightGrams).toBe(500);
    expect(result[0]!.product.currency).toBe("EUR");
  });

  it("calls fetcher for each line", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(100)
        .mockResolvedValueOnce(200),
    };
    const lines: CartLine[] = [
      { product: mkProduct("a"), quantity: 1 },
      { product: mkProduct("b"), quantity: 3 },
    ];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.unitPriceCents).toBe(100);
    expect(result[1]!.product.unitPriceCents).toBe(200);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledTimes(2);
  });

  it("throws RangeError for negative fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    const lines: CartLine[] = [
      { product: mkProduct("p1"), quantity: 1 },
    ];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(
      refreshPrices([{ product: mkProduct("p1"), quantity: 1 }], fetcher),
    ).rejects.toThrow(RangeError);
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
    };
    await expect(
      refreshPrices([{ product: mkProduct("p1"), quantity: 1 }], fetcher),
    ).rejects.toThrow("service down");
  });
});

