import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { CartConfig, CheckoutCollaborators } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker, InventoryDecision } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product, CartLine } from "../src/product.ts";

const mkProduct = (
  id: string,
  priceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: id,
  unitPriceCents: priceCents,
  weightGrams,
});

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty with 0 items", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("add() inserts a new line", () => {
    cart.add(mkProduct("a", 500), 2);
    expect(cart.itemCount).toBe(2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);
  });

  it("add() merges quantity for the same product", () => {
    cart.add(mkProduct("a", 500), 2);
    cart.add(mkProduct("a", 500), 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0]!.quantity).toBe(5);
  });

  it("add() rejects non-positive quantity", () => {
    expect(() => cart.add(mkProduct("a", 100), 0)).toThrow(RangeError);
    expect(() => cart.add(mkProduct("a", 100), -1)).toThrow(RangeError);
    expect(() => cart.add(mkProduct("a", 100), 1.5)).toThrow(RangeError);
  });

  it("add() rejects negative unitPriceCents", () => {
    expect(() => cart.add(mkProduct("a", -1), 1)).toThrow(RangeError);
  });

  it("remove() deletes existing product and returns true", () => {
    cart.add(mkProduct("a", 500), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove() returns false for unknown id", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity() changes the quantity", () => {
    cart.add(mkProduct("a", 500), 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity(0) removes the product", () => {
    cart.add(mkProduct("a", 500), 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("updateQuantity() throws for unknown product", () => {
    expect(() => cart.updateQuantity("ghost", 5)).toThrow(
      "Product ghost is not in the cart",
    );
  });

  it("updateQuantity() rejects negative quantity", () => {
    cart.add(mkProduct("a", 500), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity() rejects non-integer quantity", () => {
    cart.add(mkProduct("a", 500), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear() removes all items", () => {
    cart.add(mkProduct("a", 100), 1);
    cart.add(mkProduct("b", 200), 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot() returns a deep copy that doesn't affect cart", () => {
    cart.add(mkProduct("a", 500), 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    // Cart's internal state is unchanged
    expect(cart.snapshot()[0]!.quantity).toBe(2);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(500);
  });
});

describe("Cart — pricing pipeline (totals)", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2); // 2000
    cart.add(mkProduct("b", 500), 3); // 1500
    const t = cart.totals();
    expect(t.subtotalCents).toBe(3500);
  });

  it("applies discount then tax on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1000),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(250),
    };
    const cart = new Cart({ discountPolicy, taxCalculator });
    cart.add(mkProduct("a", 5000), 1); // subtotal = 5000

    const t = cart.totals();
    expect(t.subtotalCents).toBe(5000);
    expect(t.discountCents).toBe(1000);
    // Tax is computed on discounted subtotal (5000 - 1000 = 4000)
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(4000, "US");
    expect(t.taxCents).toBe(250);
    expect(t.totalCents).toBe(4000 + 250); // discounted + tax + 0 shipping
  });

  it("clamps discount to [0, subtotal]", () => {
    // Discount returning more than subtotal
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(mkProduct("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
    expect(t.totalCents).toBe(0); // nothing left
  });

  it("clamps negative discount to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(mkProduct("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
  });

  it("passes lines and discounted subtotal to shipping calculator", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(mkProduct("a", 1000), 1); // subtotal=1000, discount=200, discounted=800

    const t = cart.totals();
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800,
    );
    expect(t.shippingCents).toBe(599);
    expect(t.totalCents).toBe(800 + 0 + 599); // discounted + tax + shipping
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses default config when none provided", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const t = cart.totals();
    // NoDiscount → 0, NoTax → 0, FreeShipping → 0
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });

  it("empty cart totals are all zero", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("uses the region from config for tax", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator, region: "FR" });
    cart.add(mkProduct("a", 1000), 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });
});

describe("Cart — async checkout()", () => {
  const mkConfig = (overrides?: Partial<CartConfig>): CartConfig => ({
    ...overrides,
  });

  it("returns totals and lines for basic checkout without collaborators", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 500), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.product.id).toBe("a");
  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 100), 2); // old price: 100

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(200), // new price: 200
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(400); // 200 * 2
    expect(result.lines[0]!.product.unitPriceCents).toBe(200);
  });

  it("checks inventory and throws InventoryError on denial", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 100), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      } satisfies InventoryDecision),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(2);
      expect(err.message).toBe("low stock");
    }
  });

  it("throws InventoryError on partial-stock denial (available < requested)", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 100), 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      } satisfies InventoryDecision),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
  });

  it("passes when inventory is available", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 100), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      } satisfies InventoryDecision),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(200);
  });

  it("uses asyncTaxProvider for async tax computation", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ discountPolicy, region: "US-CA" });
    cart.add(mkProduct("a", 10000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1), // 10%
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(1000); // 10% of 10000
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("combines price refresh + inventory check + async tax + discount + shipping", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({
      discountPolicy,
      shippingCalculator,
      region: "US",
    });
    cart.add(mkProduct("a", 100), 2); // will be repriced to 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1000),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    // subtotal: 1000*2 = 2000
    // discount: 500
    // discounted subtotal: 1500
    // tax: 8% of 1500 = 120
    // shipping: 599
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(500);
    expect(result.totals.taxCents).toBe(120);
    expect(result.totals.shippingCents).toBe(599);
    expect(result.totals.totalCents).toBe(1500 + 120 + 599);
  });

  it("generates default denial message when reason is not provided", async () => {
    const cart = new Cart();
    cart.add(mkProduct("widget", 100), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
      } satisfies InventoryDecision),
    };

    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.message).toContain("widget");
      expect(err.available).toBe(undefined);
    }
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 100), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service error")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service error",
    );
  });

  it("does not modify internal cart state after checkout", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 500), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    await cart.checkout({ priceFetcher });

    // Internal price should still be 500
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(500);
    expect(cart.totals().subtotalCents).toBe(1000);
  });
});

